// Fill row component (Framer-style)
function FillRow({
  color,
  opacity,
  visible,
  onChange,
  onToggleVisibility,
  onRemove,
}: {
  color: string
  opacity: number
  visible: boolean
  onChange: (color: string) => void
  onToggleVisibility: () => void
  onRemove: () => void
}) {
  // Convert hex to display format (without #)
  const hexValue = color.replace("#", "").toUpperCase()

  return (
    <div className="flex items-center gap-2">
      {/* Color swatch */}
      <div className="relative">
        <input
          type="color"
          value={color}
          onChange={(e) => onChange(e.target.value)}
          className="w-8 h-8 rounded border cursor-pointer"
          style={{ backgroundColor: color }}
        />
      </div>

      {/* Hex input */}
      <Input
        value={hexValue}
        onChange={(e) => {
          const val = e.target.value.replace("#", "")
          if (/^[0-9A-Fa-f]{0,6}$/.test(val)) {
            onChange(`#${val}`)
          }
        }}
        className="h-8 font-mono text-sm flex-1 uppercase"
        maxLength={6}
      />

      {/* Opacity */}
      <div className="relative w-16">
        <Input
          type="number"
          value={opacity}
          onChange={() => {}}
          className="h-8 pr-5 font-mono text-sm text-right"
          min={0}
          max={100}
        />
        <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">%</span>
      </div>

      {/* Visibility toggle */}
      <button
        onClick={onToggleVisibility}
        className={cn("p-1 hover:bg-muted rounded", !visible && "opacity-50")}
        title={visible ? "Hide fill" : "Show fill"}
      >
        <Eye className="w-4 h-4" />
      </button>

      {/* Remove button */}
      <button
        onClick={onRemove}
        className="p-1 hover:bg-muted rounded text-muted-foreground hover:text-foreground"
        title="Remove fill"
      >
        <Minus className="w-4 h-4" />
      </button>
    </div>
  )
}

